<?php $ch = curl_init('https://overpass-api.de/api/interpreter'); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_TIMEOUT, 15); $result = curl_exec($ch); if ($result === false) { echo 'FAILED: ' . curl_error($ch); } else { echo 'SUCCESS, got ' . strlen($result) . ' bytes'; } 